import{_ as r}from"./plugin-vue_export-helper-c27b6911.js";import{r as t,o as p,c as d,d as e,e as s,b as n,w as c,a as l,f as o}from"./app-7f634a6c.js";const u={},h=e("p",null,[s('I recently built something small but useful: a channel that lets a DeepSeek Harness (dsh) instance on Linux and another on Windows talk to each other — not "SSH in and run a command", but '),e("strong",null,"two agents delegating turns and messaging each other"),s(". The result is a plugin called "),e("code",null,"dsh-peer"),s(", plus an activity dashboard that shows the remote agent's thinking as it happens.")],-1),k={href:"https://github.com/SparksDing/dsh-peer",target:"_blank",rel:"noopener noreferrer"},v=o(`<h2 id="_1-background-and-constraints" tabindex="-1"><a class="header-anchor" href="#_1-background-and-constraints" aria-hidden="true">#</a> 1. Background and constraints</h2><p>dsh ships an SDK protocol over stdio: a parent process spawns <code>dsh --profile sdk</code> and speaks JSON-RPC over stdin/stdout. There is no cross-machine channel.</p><p>Three real constraints shaped the design:</p><ol><li><strong>Windows sits behind NAT.</strong> It can only make outbound connections.</li><li><strong>The Linux side&#39;s inbound ports are blocked</strong> by the cloud security group; only HTTP-ish ports such as 80/3080 are reachable.</li><li>The thing being driven is not a bare tool process but a <strong>complete runtime</strong>: its own model route, tool set, session persistence, and filesystem.</li></ol><p>So the goal was explicit: reuse dsh&#39;s SDK protocol and add a &quot;cross-machine + symmetric&quot; layer without touching the core.</p><h2 id="_2-architecture-connection-direction-and-service-direction-are-opposite" tabindex="-1"><a class="header-anchor" href="#_2-architecture-connection-direction-and-service-direction-are-opposite" aria-hidden="true">#</a> 2. Architecture: connection direction and service direction are opposite</h2><p>This is the easiest part to get confused about, and the most important:</p><table><thead><tr><th></th><th>Establishes the connection</th><th>Sends harness requests</th><th>Responds</th></tr></thead><tbody><tr><td>hub (public side)</td><td>listens</td><td>yes (<code>session/prompt</code>)</td><td>only <code>peer/reply</code></td></tr><tr><td>link (private side)</td><td>dials</td><td>no</td><td>serves harness methods</td></tr></tbody></table><p>NAT only allows the private machine to dial out, so Windows must be the &quot;connection client&quot; — while it is simultaneously the &quot;capability server&quot;, exposing its local agent to the hub.</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>        public side (hub)                         private side (link)
  ┌──────────────────────┐                  ┌──────────────────────┐
  │ peer_ask / peer_send │  JSON-RPC reqs   │  HarnessSdkJsonRpc   │
  │ peer_wait / peer_inbox│ ───────────────► │  Server              │
  │                      │                  │   ├─ agents.create   │
  │  PeerHub             │ ◄─────────────── │   ├─ preset.mount    │
  │  links · sessions    │  session.event   │   └─ followup()      │
  └──────────────────────┘                  └──────────────────────┘
            │                                          ▲
            └──────── TCP / TLS / WebSocket ───────────┘
                       (the link always dials)
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The stack is straightforward:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>model
 │  peer_ask / peer_send / peer_wait / peer_inbox        (lib/tools.js)
 ▼
PeerHub  link registry · session state · inbox · timeouts (lib/hub.js)
 │
PeerConnection  JSON-RPC requests · heartbeat · timeouts  (lib/protocol.js)
 │
LineTransport   newline-delimited JSON-RPC 2.0 frames     (lib/transport.js)
 │
Duplex:  TCP / TLS / WebSocket                            (lib/ws.js)
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_3-protocol-reuse-the-sdk-dialect" tabindex="-1"><a class="header-anchor" href="#_3-protocol-reuse-the-sdk-dialect" aria-hidden="true">#</a> 3. Protocol: reuse the SDK dialect</h2><h3 id="_3-1-frames-and-transport" tabindex="-1"><a class="header-anchor" href="#_3-1-frames-and-transport" aria-hidden="true">#</a> 3.1 Frames and transport</h3><p>Every frame is one line of JSON-RPC 2.0: <code>method</code> + <code>id</code> is a request, <code>id</code> alone is a response, <code>method</code> alone is a notification. This matches <code>@deepseek-ai/dsh-sdk-protocol</code>, so both ends already understand the harness methods:</p><ul><li><code>initialize</code>: cwd, provider, model</li><li><code>session/prompt</code>: enqueue one user message</li><li><code>session/wait</code>, <code>session/working-directory/*</code></li><li>notifications: <code>session.event</code>, <code>session.status</code></li></ul><p>Only four methods are custom: <code>peer/hello</code>, <code>peer/ping</code>, <code>peer/info</code>, <code>peer/reply</code>, plus <code>peer/ensure-session</code> for compatibility.</p><p>Transport is pluggable because the same JSON-RPC only needs a <code>Duplex</code>:</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// lib/protocol.js</span>
<span class="token keyword">this</span><span class="token punctuation">.</span>#transport <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">LineTransport</span><span class="token punctuation">(</span>socket<span class="token punctuation">,</span> socket<span class="token punctuation">)</span>
socket<span class="token punctuation">.</span>setNoDelay<span class="token operator">?.</span><span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span>
socket<span class="token punctuation">.</span>setKeepAlive<span class="token operator">?.</span><span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token number">15_000</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-2-handshake" tabindex="-1"><a class="header-anchor" href="#_3-2-handshake" aria-hidden="true">#</a> 3.2 Handshake</h3><p>The first request from a link is:</p><div class="language-json line-numbers-mode" data-ext="json"><pre class="language-json"><code><span class="token punctuation">{</span>
  <span class="token property">&quot;jsonrpc&quot;</span><span class="token operator">:</span> <span class="token string">&quot;2.0&quot;</span><span class="token punctuation">,</span>
  <span class="token property">&quot;id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;req_...&quot;</span><span class="token punctuation">,</span>
  <span class="token property">&quot;method&quot;</span><span class="token operator">:</span> <span class="token string">&quot;peer/hello&quot;</span><span class="token punctuation">,</span>
  <span class="token property">&quot;params&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
    <span class="token property">&quot;protocol&quot;</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span>
    <span class="token property">&quot;name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;windows-pc&quot;</span><span class="token punctuation">,</span>
    <span class="token property">&quot;role&quot;</span><span class="token operator">:</span> <span class="token string">&quot;link&quot;</span><span class="token punctuation">,</span>
    <span class="token property">&quot;token&quot;</span><span class="token operator">:</span> <span class="token string">&quot;&lt;shared secret&gt;&quot;</span><span class="token punctuation">,</span>
    <span class="token property">&quot;platform&quot;</span><span class="token operator">:</span> <span class="token string">&quot;win32&quot;</span><span class="token punctuation">,</span>
    <span class="token property">&quot;cwd&quot;</span><span class="token operator">:</span> <span class="token string">&quot;C:\\\\Users\\\\admin&quot;</span><span class="token punctuation">,</span>
    <span class="token property">&quot;provider&quot;</span><span class="token operator">:</span> <span class="token string">&quot;deepseek-official&quot;</span><span class="token punctuation">,</span>
    <span class="token property">&quot;model&quot;</span><span class="token operator">:</span> <span class="token string">&quot;deepseek-v4-flash&quot;</span>
  <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The hub checks the protocol version and compares the token in constant time, refusing anything that does not match. After that:</p><ul><li>an application-level <code>peer/ping</code> every 25 seconds, dropping the connection after two consecutive misses;</li><li>on disconnect, the link reconnects with exponential backoff from 1s up to 30s.</li></ul><h3 id="_3-3-one-peer-ask-end-to-end" tabindex="-1"><a class="header-anchor" href="#_3-3-one-peer-ask-end-to-end" aria-hidden="true">#</a> 3.3 One <code>peer_ask</code>, end to end</h3><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>me: peer_ask(peer=&quot;HP&quot;, prompt=&quot;check disk&quot;)
 │
 ├─ hub.require(&quot;HP&quot;)                     resolve by name (or unique substring)
 ├─ sessionId = peer-HP-default           identity = link name + topic
 ├─ initialize {cwd, provider, model}     once per connection
 ├─ peer/ensure-session {sessionId}       link tries to resume; otherwise prompt creates it
 ├─ session/prompt {sessionId, blocks} ──► link
 │                                          └─ PeerHarnessServer
 │                                             ├─ agentPresets.resolve(&quot;standard&quot;)
 │                                             ├─ agents.create/resume
 │                                             │   setup: preset.mount(agentCtx)
 │                                             └─ agent.followup(userMessage)
 │                                                ↓ a real model turn with real tools
 │                                          ◄── session.event  (streamed)
 │                                          ◄── session.status (running/idle)
 ├─ hub sees agent/inbox/spliced           message admitted (correlated by messageId)
 ├─ hub waits for idle and idleCount bump  turn is over
 └─ returns the last assistant/message text
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>One subtle implementation detail: <strong>the hub does not use <code>session/wait</code> to detect the end of a turn</strong>. The 0.2.0 SDK server only implements <code>initialize</code>, <code>session/prompt</code>, and <code>shutdown</code>. Instead, the hub keeps per-session state on each connection:</p><ul><li><code>receipts</code>: messageIds confirmed by <code>agent/inbox/spliced</code></li><li><code>idleCount</code>: how many times <code>session.status</code> became idle</li><li><code>lastAssistant</code>: text of the last assistant message</li></ul><p>The wait condition is &quot;idleCount increased since before the prompt&quot;, not &quot;wait for an idle notification&quot; — the latter loses the event when the turn finishes before the wait starts.</p><h3 id="_3-4-session-identity-and-continuity" tabindex="-1"><a class="header-anchor" href="#_3-4-session-identity-and-continuity" aria-hidden="true">#</a> 3.4 Session identity and continuity</h3><p>Session ids are <code>peer-&lt;link&gt;-&lt;topic&gt;</code>:</p><ul><li>reusing a <code>session</code> name continues the same conversation; <code>fresh: true</code> starts a new one;</li><li>after a reconnect the hub re-runs <code>initialize</code>, then <code>peer/ensure-session</code> for existing conversations;</li><li>the link first tries <code>session/resume</code> to load persisted history; if that fails (first use), the next prompt creates it.</li></ul><p>Conversations therefore survive restarts of either side.</p><h3 id="_3-5-event-filtering" tabindex="-1"><a class="header-anchor" href="#_3-5-event-filtering" aria-hidden="true">#</a> 3.5 Event filtering</h3><p><code>HarnessSdkJsonRpcServer</code> broadcasts <code>session.event</code> for <strong>every session in the runtime</strong>. For a peer channel that is both wasteful and a privacy leak, so the link wraps the transport:</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token function">notify</span><span class="token punctuation">(</span><span class="token parameter">method<span class="token punctuation">,</span> params</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span>method <span class="token operator">===</span> <span class="token string">&#39;session.event&#39;</span> <span class="token operator">||</span> method <span class="token operator">===</span> <span class="token string">&#39;session.status&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>owned<span class="token punctuation">.</span><span class="token function">has</span><span class="token punctuation">(</span>params<span class="token punctuation">.</span>sessionId<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token keyword">return</span>
  <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>method <span class="token operator">===</span> <span class="token string">&#39;subagent.started&#39;</span> <span class="token operator">||</span> method <span class="token operator">===</span> <span class="token string">&#39;subagent.finished&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>owned<span class="token punctuation">.</span><span class="token function">has</span><span class="token punctuation">(</span>params<span class="token punctuation">.</span>parentSessionId<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token keyword">return</span>
  <span class="token punctuation">}</span>
  conn<span class="token punctuation">.</span><span class="token function">notify</span><span class="token punctuation">(</span>method<span class="token punctuation">,</span> params<span class="token punctuation">)</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>owned</code> is populated when <code>session/prompt</code> or <code>session/resume</code> arrives, so only sessions created by this peer connection are forwarded.</p><h2 id="_4-backend-details-worth-noting" tabindex="-1"><a class="header-anchor" href="#_4-backend-details-worth-noting" aria-hidden="true">#</a> 4. Backend details worth noting</h2><h3 id="_4-1-tools-come-from-agent-presets-not-the-global-plane" tabindex="-1"><a class="header-anchor" href="#_4-1-tools-come-from-agent-presets-not-the-global-plane" aria-hidden="true">#</a> 4.1 Tools come from agent presets, not the global plane</h3><p>Mounting the link in the <code>web</code> profile hits a snag: peer sessions only see globally registered tools (<code>peer_reply</code>, <code>peer_status</code>) — no <code>bash</code>, <code>read</code>, or <code>write</code>, because the Web profile moves every model-facing tool row into an agent preset.</p><p>The fix is to subclass <code>HarnessSdkJsonRpcServer</code> and override <code>createSession</code> so the preset is mounted in the pre-publication <code>setup</code> hook:</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">const</span> preset <span class="token operator">=</span> <span class="token keyword">await</span> presets<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>presetId<span class="token punctuation">)</span>   <span class="token comment">// defaults to the registry default</span>
<span class="token function-variable function">setup</span> <span class="token operator">=</span> <span class="token keyword">async</span> <span class="token punctuation">(</span><span class="token parameter">agentCtx</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
  <span class="token keyword">await</span> presets<span class="token punctuation">.</span><span class="token function">mount</span><span class="token punctuation">(</span>agentCtx<span class="token punctuation">,</span> preset<span class="token punctuation">.</span>id<span class="token punctuation">)</span>
<span class="token punctuation">}</span>
<span class="token keyword">const</span> handle <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token keyword">this</span><span class="token punctuation">.</span>ctx<span class="token punctuation">.</span>agents<span class="token punctuation">.</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">{</span>
  sessionId<span class="token punctuation">,</span>
  <span class="token literal-property property">meta</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">cwd</span><span class="token operator">:</span> <span class="token keyword">this</span><span class="token punctuation">.</span>cwd<span class="token punctuation">,</span> <span class="token literal-property property">agentPreset</span><span class="token operator">:</span> preset<span class="token punctuation">.</span>id <span class="token punctuation">}</span><span class="token punctuation">,</span>
  agentOptions<span class="token punctuation">,</span>
  setup<span class="token punctuation">,</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>setup</code> runs before the agent is published, so the preset&#39;s tools exist when the first prompt is assembled.</p><h3 id="_4-2-older-versions-have-no-session-resume" tabindex="-1"><a class="header-anchor" href="#_4-2-older-versions-have-no-session-resume" aria-hidden="true">#</a> 4.2 Older versions have no <code>session/resume</code></h3><p>0.2.0&#39;s SDK server exposes only three methods, and <code>agents.create</code> on an existing session id fails with <code>session &quot;...&quot; already exists</code>. The compatibility path catches that and falls back to <code>agents.resume</code>:</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">try</span> <span class="token punctuation">{</span>
  handle <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token keyword">this</span><span class="token punctuation">.</span>ctx<span class="token punctuation">.</span>agents<span class="token punctuation">.</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">{</span> sessionId<span class="token punctuation">,</span> meta<span class="token punctuation">,</span> agentOptions<span class="token punctuation">,</span> setup <span class="token punctuation">}</span><span class="token punctuation">)</span>
<span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span>error<span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">already exists</span><span class="token regex-delimiter">/</span><span class="token regex-flags">i</span></span><span class="token punctuation">.</span><span class="token function">test</span><span class="token punctuation">(</span>error<span class="token punctuation">.</span>message<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token keyword">throw</span> error
  handle <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token keyword">this</span><span class="token punctuation">.</span>ctx<span class="token punctuation">.</span>agents<span class="token punctuation">.</span><span class="token function">resume</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">resumeSessionId</span><span class="token operator">:</span> sessionId<span class="token punctuation">,</span> agentOptions<span class="token punctuation">,</span> setup <span class="token punctuation">}</span><span class="token punctuation">)</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-3-when-only-an-http-port-is-reachable-websocket-plus-a-bridge" tabindex="-1"><a class="header-anchor" href="#_4-3-when-only-an-http-port-is-reachable-websocket-plus-a-bridge" aria-hidden="true">#</a> 4.3 When only an HTTP port is reachable: WebSocket plus a bridge</h3><p>The public side&#39;s 3099 is blocked by the security group, but 3080 works (nginx). So one path was added:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>link --ws--&gt; nginx (/dsh-peer) --ws--&gt; peer-ws-bridge --tcp--&gt; hub:3099
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>The bridge is tiny: it accepts the WebSocket upgrade and pipes each connection to the hub&#39;s TCP port. The hub stays unchanged and keeps listening on raw TCP.</p><p>nginx needs one exact-match location that does not disturb the dsh GUI:</p><div class="language-nginx line-numbers-mode" data-ext="nginx"><pre class="language-nginx"><code><span class="token directive"><span class="token keyword">location</span> = /dsh-peer</span> <span class="token punctuation">{</span>
    <span class="token directive"><span class="token keyword">proxy_pass</span> http://127.0.0.1:3098</span><span class="token punctuation">;</span>
    <span class="token directive"><span class="token keyword">proxy_http_version</span> 1.1</span><span class="token punctuation">;</span>
    <span class="token directive"><span class="token keyword">proxy_set_header</span> Upgrade <span class="token variable">$http_upgrade</span></span><span class="token punctuation">;</span>
    <span class="token directive"><span class="token keyword">proxy_set_header</span> Connection <span class="token string">&quot;upgrade&quot;</span></span><span class="token punctuation">;</span>
    <span class="token directive"><span class="token keyword">proxy_read_timeout</span> <span class="token number">86400s</span></span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-4-binary-artifacts-get-a-separate-upload-endpoint" tabindex="-1"><a class="header-anchor" href="#_4-4-binary-artifacts-get-a-separate-upload-endpoint" aria-hidden="true">#</a> 4.4 Binary artifacts get a separate upload endpoint</h3><p>The protocol carries JSON text only. Pushing screenshots or preview QR codes through JSON-RPC (base64) is expensive and fragile, so there is a small token-checked upload endpoint:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>PUT http://hub:3080/peer-files/upload/shot1.png?token=...
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>On the remote side, <code>Invoke-WebRequest -Method Put -InFile</code> is enough.</p><h2 id="_5-frontend-the-activity-dashboard" tabindex="-1"><a class="header-anchor" href="#_5-frontend-the-activity-dashboard" aria-hidden="true">#</a> 5. Frontend: the activity dashboard</h2><h3 id="_5-1-why-it-lives-in-the-bridge" tabindex="-1"><a class="header-anchor" href="#_5-1-why-it-lives-in-the-bridge" aria-hidden="true">#</a> 5.1 Why it lives in the bridge</h3><p>The requirement was to see the remote agent&#39;s <strong>thinking</strong> and details: user messages, reasoning, assistant text, tool calls and results, turn boundaries, status changes.</p><p>The obvious approach — a dsh client UI plugin — has two problems:</p><ol><li>Its data plane needs typert Remote descriptors, which are <strong>generated at build time</strong>; out-of-tree plugins have a hard time wiring that up.</li><li>More importantly, adding a read-only panel should not require restarting the hub that is already running.</li></ol><p>The WebSocket bridge happens to sit between the link and the hub and <strong>sees every JSON-RPC frame</strong>. So the dashboard was implemented there: the bridge parses frames on the side, feeds an in-memory store, and serves a minimal HTTP page.</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>link --ws--&gt; nginx(/dsh-peer) --&gt; bridge --tcp--&gt; hub(3099)
                                   │
                                   ├─ parse session.event / session.status
                                   └─ nginx(/peer-ui/) --&gt; GET / and GET /api/activity
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Neither the hub nor the link changed.</p><h3 id="_5-2-event-model" tabindex="-1"><a class="header-anchor" href="#_5-2-event-model" aria-hidden="true">#</a> 5.2 Event model</h3><p>dsh session events are a discriminated union. The dashboard keeps the ones worth showing:</p><table><thead><tr><th>Event</th><th>Display</th></tr></thead><tbody><tr><td><code>user/message</code></td><td>user or injected message text</td></tr><tr><td><code>assistant/message</code></td><td>split into <code>reasoning</code> and <code>text</code> blocks</td></tr><tr><td><code>tool/call</code></td><td>tool name + argument JSON</td></tr><tr><td><code>tool/result</code></td><td>result text, red when <code>isError</code></td></tr><tr><td><code>turn/start</code> / <code>turn/end</code></td><td>turn boundaries and end reason</td></tr><tr><td><code>session.status</code></td><td>running / idle</td></tr></tbody></table><p>Each event is flattened into a ring buffer:</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token punctuation">{</span> seq<span class="token punctuation">,</span> at<span class="token punctuation">,</span> kind<span class="token punctuation">,</span> title<span class="token operator">?</span><span class="token punctuation">,</span> text<span class="token operator">?</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><code>seq</code> is globally monotonic, which makes incremental fetching trivial.</p><h3 id="_5-3-incremental-polling" tabindex="-1"><a class="header-anchor" href="#_5-3-incremental-polling" aria-hidden="true">#</a> 5.3 Incremental polling</h3><p>No push channel — just polling every 900 ms with a <code>since</code> cursor:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>GET /api/activity?since=123&amp;token=...
→ { now, seq, peers: [ { name, sessions: [ { id, status, events: [...] } ] } ] }
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>Only events with <code>seq &gt; since</code> come back, so responses stay small. The server keeps the last 400 events per session and 4000 overall, dropping the oldest from the least recently active session.</p><p>Polling instead of SSE is a pragmatic choice: a dashboard is usually watched briefly, and failure recovery (refresh, reconnect) costs almost no code.</p><h3 id="_5-4-rendering" tabindex="-1"><a class="header-anchor" href="#_5-4-rendering" aria-hidden="true">#</a> 5.4 Rendering</h3><p>The page is <strong>one self-contained HTML string</strong> with no external assets and no frontend build step — a function returns it directly:</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">export</span> <span class="token keyword">function</span> <span class="token function">dashboardHtml</span><span class="token punctuation">(</span><span class="token parameter">token</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">return</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">&lt;!doctype html&gt;
  &lt;html&gt;…&lt;script&gt;
    let since = 0
    async function tick() {
      const r = await fetch(&#39;api/activity?since=&#39; + since + &#39;&amp;token=&#39; + encodeURIComponent(TOKEN))
      const data = await r.json()
      render(data)
      since = Math.max(since, data.seq)
    }
    setInterval(tick, 900)
  &lt;/script&gt;&lt;/html&gt;</span><span class="token template-punctuation string">\`</span></span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Rendering groups by session; new events are appended to the end. The header shows a peer status dot (green when any session is running), and an optional &quot;follow&quot; checkbox keeps the view scrolled to the bottom.</p><p>The result is a chronological stream: purple for reasoning, yellow for tool calls, green for results, red for failures, gray for turn boundaries.</p><h3 id="_5-5-security" tabindex="-1"><a class="header-anchor" href="#_5-5-security" aria-hidden="true">#</a> 5.5 Security</h3><p>The dashboard runs on the public 3080, so:</p><ul><li>both the page and the JSON endpoint require a <code>token</code> query parameter;</li><li>the page embeds that token into its fetches;</li><li>the bridge is read-only and exposes no write endpoint.</li></ul><h2 id="_6-real-world-validation" tabindex="-1"><a class="header-anchor" href="#_6-real-world-validation" aria-hidden="true">#</a> 6. Real-world validation</h2><p>This was not a paper design; it ran end to end on real machines:</p><ol><li>Windows runs <code>dsh --profile sdk</code> as a link and connects to the Linux hub over <code>ws://…/dsh-peer</code>;</li><li>on Linux, <code>peer_ask(peer=&quot;HP&quot;, prompt=&quot;check disk&quot;)</code> makes the Windows agent run pwsh and return the result;</li><li>the agent then drives WeChat DevTools through <code>miniprogram-automator</code>, reads page elements, takes screenshots, and uploads the preview QR code and screenshots back through the upload endpoint;</li><li>the dashboard shows its reasoning, tool calls, and results step by step.</li></ol><p>Pitfalls worth recording:</p><ul><li><strong>Web profile tools live in presets</strong>, and only peer tools are global;</li><li><strong>0.2.0 has no <code>session/resume</code></strong>, so reconnects must fall back to <code>agents.resume</code>;</li><li><strong>HMR only replaces plugin files inside the profile directory</strong>; new files outside it are not hot-loaded — which is why the bridge became a standalone process;</li><li><strong>The Windows sandbox requires temp to be outside the workspace</strong>; when the workspace is the home directory, <code>%LOCALAPPDATA%\\Temp</code> is inside it and startup is refused;</li><li><strong>The WeChat DevTools CLI writes to <code>%LOCALAPPDATA%</code></strong>, so a workspace outside the home directory blocks it; its service port must be enabled manually, and preview requires a real AppID (<code>touristappid</code> fails with &quot;AppID does not exist&quot;).</li></ul><h2 id="_7-limitations-and-next-steps" tabindex="-1"><a class="header-anchor" href="#_7-limitations-and-next-steps" aria-hidden="true">#</a> 7. Limitations and next steps</h2><ul><li>The link agent is event-driven: it runs only when prompted. It can interject with <code>peer_reply</code> during a turn, but cannot start one on its own.</li><li>The dashboard only covers links that go through the bridge; a direct TCP link would need the same recording logic inside the hub.</li><li>With multiple users or machines, events would need subscriptions and per-peer permissions (today the token is all-or-nothing).</li><li>Embedding the panel inside the dsh Web GUI would need a client plugin plus typert descriptors — significantly more work, so it stays a standalone page for now.</li></ul><h2 id="_8-code" tabindex="-1"><a class="header-anchor" href="#_8-code" aria-hidden="true">#</a> 8. Code</h2>`,91),m={href:"https://github.com/SparksDing/dsh-peer",target:"_blank",rel:"noopener noreferrer"},b=o("<li>Backend: <code>lib/protocol.js</code>, <code>lib/hub.js</code>, <code>lib/link.js</code>, <code>lib/link-server.js</code></li><li>Transport: <code>lib/transport.js</code>, <code>lib/ws.js</code></li><li>Dashboard: <code>lib/activity.js</code> (event model + HTML), <code>bin/peer-ws-bridge.mjs</code> (side parsing + HTTP endpoints)</li><li>Tests: <code>node test/hub.test.mjs</code>, <code>node test/tools.test.mjs</code> (no model and no dsh required)</li>",4),g=e("p",null,'If the approach is useful to you, take it and adapt it. Issues about better observability are welcome — especially "how to observe a process without modifying it".',-1);function y(w,f){const a=t("ExternalLinkIcon"),i=t("RouterLink");return p(),d("div",null,[h,e("p",null,[s("Code: "),e("a",k,[s("SparksDing/dsh-peer"),n(a)]),s(". This post covers the design, the interaction flow, and why the dashboard lives inside the bridge.")]),e("blockquote",null,[e("p",null,[s("中文版: "),n(i,{to:"/architecture/dsh-peer.html"},{default:c(()=>[s("让两个 DeepSeek Harness 跨机器对话")]),_:1})])]),l(" more "),v,e("ul",null,[e("li",null,[s("Repository: "),e("a",m,[s("SparksDing/dsh-peer"),n(a)])]),b]),g])}const q=r(u,[["render",y],["__file","dsh-peer.html.vue"]]);export{q as default};
